htmlform.script:
$j(function() {
    var rows = $j('.anesthesia-item-row');
    var addButton = $j('#add-anesthesia-gas');

    function cellHasValue(cell) {
        var hasControlValue = false;
        cell.find('input:not([type="hidden"]):not([type="button"]), textarea, select').each(function() {
            var input = $j(this);
            if ((input.is(':checkbox') || input.is(':radio')) ? input.is(':checked') : input.val()) {
                hasControlValue = true;
            }
        });
        return hasControlValue || $j.trim(cell.text()).length > 0;
    }

    function rowHasValue(row) {
        return cellHasValue(row.find('.item-value').eq(0)) || cellHasValue(row.find('.item-value').eq(1));
    }

    function updateControls() {
        var visibleRows = rows.filter(':visible');
        visibleRows.find('.remove-item').prop('disabled', visibleRows.length === 1);
        addButton.prop('disabled', rows.filter(':hidden').length === 0);
    }

    rows.each(function(index) {
        var row = $j(this);
        if (index === 0 || rowHasValue(row)) {
            row.show();
        }
    });

    addButton.on('click', function() {
        rows.filter(':hidden').first().show();
        updateControls();
    });

    rows.on('click', '.remove-item', function() {
        var row = $j(this).closest('.anesthesia-item-row');
        row.find('input:not([type="hidden"]), textarea, select').each(function() {
            var input = $j(this);
            if (input.is(':checkbox') || input.is(':radio')) {
                input.prop('checked', false);
            }
            else {
                input.val('');
            }
            input.trigger('change');
        });
        row.hide();
        updateControls();
    });

    if (typeof beforeSubmit !== 'undefined') {
        beforeSubmit.push(function() {
            var hasCompleteRow = false;
            var hasPartialRow = false;
            rows.filter(':visible').each(function() {
                var cells = $j(this).find('.item-value');
                var hasAgent = cellHasValue(cells.eq(0));
                var hasConcentration = cellHasValue(cells.eq(1));
                hasCompleteRow = hasCompleteRow || (hasAgent && hasConcentration);
                hasPartialRow = hasPartialRow || (hasAgent !== hasConcentration);
            });
            if (hasPartialRow) {
                alert('Enter both the inhaled agent and concentration for each gas row.');
                return false;
            }
            if (!hasCompleteRow) {
                alert('Enter at least one gas observation before saving.');
                return false;
            }
            return true;
        });
    }

    updateControls();
});
